    TinyIntVector tinyIntVector = (TinyIntVector) vector;
    tinyIntVector.setInitialCapacity(3);
    tinyIntVector.allocateNew(3);
    tinyIntVector.setSafe(0, 1);
    tinyIntVector.setSafe(1, 2);
