    timecharVector.setSafe(0, "2008-08-08 00:00:00".getBytes());
    timecharVector.setIndexDefined(1);
    timecharVector.setValueLengthSafe(1, 5);
    timecharVector.setSafe(1, "1900-08-08 00:00:00".getBytes());
