@Test
public void compareTest() throws AnalysisException {
    PartitionKey pk1;
    PartitionKey pk2;
    // case1
    pk1 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("127"), new PartitionValue("32767")), Arrays.asList(tinyInt, smallInt));
    pk2 = PartitionKey.createInfinityPartitionKey(Arrays.asList(tinyInt, smallInt), true);
    Assert.assertTrue(!pk1.equals(pk2) && pk1.compareTo(pk2) == -1);
    // case2
    pk1 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("127")), Arrays.asList(tinyInt, smallInt));
    pk2 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("127"), new PartitionValue("-32768")), Arrays.asList(tinyInt, smallInt));
    Assert.assertTrue(pk1.equals(pk2) && pk1.compareTo(pk2) == 0);
    // case3
    pk1 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("127")), Arrays.asList(int32, bigInt));
    pk2 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("128"), new PartitionValue("-32768")), Arrays.asList(int32, bigInt));
    Assert.assertTrue(!pk1.equals(pk2) && pk1.compareTo(pk2) == -1);
    // case4
    pk1 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("127"), new PartitionValue("12345")), Arrays.asList(largeInt, bigInt));
    pk2 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("127"), new PartitionValue("12346")), Arrays.asList(largeInt, bigInt));
    Assert.assertTrue(!pk1.equals(pk2) && pk1.compareTo(pk2) == -1);
    // case5
    pk1 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("2014-12-12"), new PartitionValue("2014-12-12 10:00:00")), Arrays.asList(date, datetime));
    pk2 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("2014-12-12"), new PartitionValue("2014-12-12 10:00:01")), Arrays.asList(date, datetime));
    Assert.assertTrue(!pk1.equals(pk2) && pk1.compareTo(pk2) == -1);
    // case6
    pk1 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("-128")), Arrays.asList(tinyInt, smallInt));
    pk2 = PartitionKey.createInfinityPartitionKey(Arrays.asList(tinyInt, smallInt), false);
    Assert.assertTrue(pk1.equals(pk2) && pk1.compareTo(pk2) == 0);
    // case7
    pk1 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("127")), Arrays.asList(tinyInt, smallInt));
    pk2 = PartitionKey.createInfinityPartitionKey(Arrays.asList(tinyInt, smallInt), true);
    Assert.assertTrue(!pk1.equals(pk2) && pk1.compareTo(pk2) == -1);
    // case7
    pk1 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("127"), new PartitionValue("32767")), Arrays.asList(tinyInt, smallInt));
    pk2 = PartitionKey.createInfinityPartitionKey(Arrays.asList(tinyInt, smallInt), true);
    Assert.assertTrue(!pk1.equals(pk2) && pk1.compareTo(pk2) == -1);
    // case8
    pk1 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("127"), new PartitionValue("32767"), new PartitionValue("2147483647"), new PartitionValue("9223372036854775807"), new PartitionValue("170141183460469231731687303715884105727"), new PartitionValue("9999-12-31"), new PartitionValue("9999-12-31 23:59:59")), allColumns);
    pk2 = PartitionKey.createInfinityPartitionKey(allColumns, true);
    Assert.assertTrue(!pk1.equals(pk2) && pk1.compareTo(pk2) == -1);
    // case9
    pk1 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("-128"), new PartitionValue("-32768"), new PartitionValue("-2147483648"), new PartitionValue("-9223372036854775808"), new PartitionValue("-170141183460469231731687303715884105728"), new PartitionValue("1900-01-01"), new PartitionValue("1900-01-01 00:00:00")), allColumns);
    pk2 = PartitionKey.createInfinityPartitionKey(allColumns, false);
    Assert.assertTrue(pk1.equals(pk2) && pk1.compareTo(pk2) == 0);
    // case10
    pk1 = PartitionKey.createPartitionKey(Arrays.asList(new PartitionValue("-128"), new PartitionValue("-32768"), new PartitionValue("0"), new PartitionValue("-9223372036854775808"), new PartitionValue("0"), new PartitionValue("1970-01-01"), new PartitionValue("1970-01-01 00:00:00")), allColumns);
    pk2 = PartitionKey.createInfinityPartitionKey(allColumns, false);
    Assert.assertTrue(!pk1.equals(pk2) && pk1.compareTo(pk2) == 1);
}

