    Assert.assertEquals(expected, balancedBackendsPerBucketSeq);
    // 2. balance a already balanced group
    colocateTableIndex = createColocateIndex(groupId, Lists.newArrayList(9L, 8L, 7L, 8L, 6L, 5L, 9L, 4L, 1L, 2L, 3L, 4L, 1L, 2L, 3L));
