public void test() throws InterruptedException {
    Thread t1 = new Thread(new Runnable() {

        @Override
        public void run() {
            lock.lock();
            try {
                try {
                    Thread.sleep(5000);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            } finally {
                lock.unlock();
            }
        }
    }, "thread1");
    Thread t2 = new Thread(new Runnable() {

        @Override
        public void run() {
