    }
    {
        PartitionKey hashKey = new PartitionKey();
        hashKey.pushColumn(new IntLiteral(4), PrimitiveType.BIGINT);
        long hashValue = hashKey.getHashValue();
        long mod = (int) ((hashValue & 0xffffffff) % 3);
